// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        address actor = address(0xBEEF);
        amount = bound(amount, 1 ether, 100 ether);
        vm.deal(actor, amount);

        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 beforeBal = c.balances(actor);
        vm.assume(beforeBal >= amount);

        vm.prank(actor);
        try c.CashOut(amount) {
            uint256 afterBal = c.balances(actor);
            assertTrue(afterBal == beforeBal - amount);
        } catch {
            assertTrue(c.balances(actor) == beforeBal);
        }
    }
}
